#!/bin/bash\n\n# Color codes for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\necho -e \"${YELLOW}=== Terraform Drift Detector - Test Suite ===${NC}\"\necho \"\"\n\n# Run unit tests\necho -e \"${YELLOW}Running unit tests...${NC}\"\ngo test -v -race -timeout 10m ./internal/drift ./internal/state ./internal/store\nUNIT_RESULT=$?\n\nif [ $UNIT_RESULT -eq 0 ]; then\n    echo -e \"${GREEN}✓ Unit tests passed${NC}\"\nelse\n    echo -e \"${RED}✗ Unit tests failed${NC}\"\n    exit 1\nfi\n\necho \"\"\necho -e \"${YELLOW}Running benchmarks (small dataset)...${NC}\"\ngo test -bench=BenchmarkCompareSmall -benchmem ./internal/drift\necho \"\"\ngo test -bench=BenchmarkSaveScan -benchmem ./internal/store\necho \"\"\ngo test -bench=BenchmarkNormalizeSmall -benchmem ./internal/state\n\necho \"\"\necho -e \"${YELLOW}Running benchmarks (large dataset)...${NC}\"\ngo test -bench=BenchmarkCompareLarge -benchmem ./internal/drift\necho \"\"\ngo test -bench=BenchmarkListScans -benchmem ./internal/store\necho \"\"\ngo test -bench=BenchmarkNormalizeLarge -benchmem ./internal/state\n\necho \"\"\necho -e \"${YELLOW}Running code coverage...${NC}\"\ngo test -coverprofile=coverage.out ./internal/drift ./internal/state ./internal/store\ngo tool cover -html=coverage.out -o coverage.html\n\necho \"\"\necho -e \"${GREEN}=== All tests completed successfully ===${NC}\"\necho -e \"${GREEN}✓ Unit tests passed${NC}\"\necho -e \"${GREEN}✓ Benchmarks completed${NC}\"\necho -e \"${GREEN}✓ Coverage report generated (coverage.html)${NC}\"\n"